using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class TruceNegotiationTests
{
    internal static readonly EntityId Own=new("org:negotiator"),Oda=new("org:oda"),Head=new("person:nobunaga");
    internal static WorldSession Start(bool policy=true){var p=NewGameWorldTests.Officer(role:StartTemplate.Daimyo,site:"site:fork");var setup=NewGameWorldTests.Setup([p],[new(p.Id,Own.Value,[p.Site],false)]);return new(NewGameWorld.Create(setup.World,setup.Registered,p.Id,worldArmyPolicy:NpcArmies.CompactCombatPolicy,trucePolicy:policy?TruceNegotiations.Policy:null));}
    static CommandResult Offer(WorldSession s,int days,string id="request:truce-offer")=>s.NegotiateTruce(new(new(id),TruceAction.Propose,Own,Oda,null,days),s.PlayerControl,s.Revision);
    static void Send(WorldSession s,int days){var r=Offer(s,days);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    internal static void Advance(WorldSession s,long at){while(s.Seconds<at){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>old);}}
    static TrucePaper Last(WorldSession s,TruceAction action)=>s.DiagnosticSnapshot().Truces!.Papers.Last(p=>p.Input.Action==action);
    static long Arrival(WorldSession s,TrucePaper p)=>s.DiagnosticSnapshot().Couriers!.Missions.Single(c=>s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==c.Attempt&&a.MessageId==p.Message)).ReadyAt;
    static void ReceiveReply(WorldSession s,int days){Send(s,days);var offer=Last(s,TruceAction.Propose);Advance(s,Arrival(s,offer)+1);var reply=Last(s,days>30?TruceAction.Counter:TruceAction.Accept);Advance(s,Arrival(s,reply));}
    static void Open(WorldSession s,TrucePaper p){var r=s.Open(s.PlayerControl,new(p.Message),s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    [Fact]public void ProposalDoesNotCreateTreatyOrRevealCounterpartyReply(){var s=Start();Send(s,90);var w=s.DiagnosticSnapshot();Assert.Single(w.Truces!.Papers);Assert.Empty(w.Truces.Formations);Assert.Empty(TruceNegotiations.Known(w,Head));Assert.Single(s.TruceView());Assert.Contains(new EntityId(w.Truces.Papers[0].Message),w.SealedMessages);}
    [Fact]public void AcceptanceFormsOnlyOnPhysicalArrivalAndPlayerKnowledgeOnlyOnOpening(){var s=Start();Send(s,10);var p=Last(s,TruceAction.Propose);Advance(s,Arrival(s,p)+1);var reply=Last(s,TruceAction.Accept);Advance(s,Arrival(s,reply)-1);Assert.Empty(s.DiagnosticSnapshot().Truces!.Formations);Advance(s,Arrival(s,reply));Assert.Single(s.DiagnosticSnapshot().Truces!.Formations);Assert.Empty(TruceNegotiations.Known(s.DiagnosticSnapshot(),s.PlayerControl));Open(s,reply);Assert.Single(TruceNegotiations.Known(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Single(s.DiagnosticSnapshot().Truces!.Fulfillments);}
    [Fact]public void LongOfferGetsExplicitNewVersionAndNeedsNewPlayerConsent(){var s=Start();ReceiveReply(s,90);var p=Last(s,TruceAction.Counter);Assert.Equal(2,p.Terms.Version);Assert.Equal(30*86400,p.Terms.Until-p.Terms.From);Assert.Empty(s.DiagnosticSnapshot().Truces!.Formations);Assert.DoesNotContain(s.TruceView(),c=>c.CanAccept);var input=new TruceInput(new("request:accept-counter"),TruceAction.Accept,Own,Oda,p.Input.Id);Assert.Equal(ResultCode.NotAvailable,s.NegotiateTruce(input,s.PlayerControl,s.Revision).Code);Open(s,p);Assert.Contains(s.TruceView(),c=>c.CanAccept&&c.Version==2);Assert.Equal(ResultCode.Accepted,s.NegotiateTruce(input,s.PlayerControl,s.Revision).Code);var accept=Last(s,TruceAction.Accept);Assert.Empty(s.DiagnosticSnapshot().Truces!.Formations);Advance(s,Arrival(s,accept));Assert.Single(s.DiagnosticSnapshot().Truces!.Formations);Assert.Single(TruceNegotiations.Known(s.DiagnosticSnapshot(),Head));Assert.Empty(TruceNegotiations.Known(s.DiagnosticSnapshot(),s.PlayerControl));var confirm=Last(s,TruceAction.Confirm);Advance(s,Arrival(s,confirm));Open(s,confirm);Assert.Single(TruceNegotiations.Known(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact]public void DecliningCounterDoesNotTransferMoneyTroopsOrCreateAgreement(){var s=Start();ReceiveReply(s,90);var p=Last(s,TruceAction.Counter);Open(s,p);var w=s.DiagnosticSnapshot();Assert.Equal(ResultCode.Accepted,s.NegotiateTruce(new(new("request:decline"),TruceAction.Decline,Own,Oda,p.Input.Id),s.PlayerControl,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Truces!.Formations);Assert.Equal(ContractJson.Write(w.ResourceLots),ContractJson.Write(s.DiagnosticSnapshot().ResourceLots));Assert.Equal(ContractJson.Write(w.Units),ContractJson.Write(s.DiagnosticSnapshot().Units));}
    [Theory][InlineData(0)][InlineData(-1)][InlineData(91)]public void UnsupportedDurationDoesNotChangeWorld(int days){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Offer(s,days).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void IdempotencyAndRevisionDoNotDuplicatePaperOrFormation(){var s=Start();var i=new TruceInput(new("request:offer"),TruceAction.Propose,Own,Oda,null,10);Assert.Equal(ResultCode.StateChanged,s.NegotiateTruce(i,s.PlayerControl,999).Code);Assert.Equal(ResultCode.Accepted,s.NegotiateTruce(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.NegotiateTruce(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.NegotiateTruce(i with{Days=11},s.PlayerControl,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().Truces!.Papers);}
    [Fact]public void AnotherActorCannotSignAsPlayerOwner(){var s=Start();Assert.Equal(ResultCode.NotAvailable,s.NegotiateTruce(new(new("request:foreign"),TruceAction.Propose,Own,Oda,null,10),Head,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.NegotiateTruce(new(new("request:foreign-owner"),TruceAction.Propose,Oda,Own,null,10),s.PlayerControl,s.Revision).Code);}
    [Fact]public void ConfirmedTermsAndOpeningCannotBeForged(){var s=Start();ReceiveReply(s,90);var w=s.DiagnosticSnapshot();var p=w.Truces!.Papers.Last();w.Truces=w.Truces with{Papers=[w.Truces.Papers[0],p with{Terms=p.Terms with{Version=1}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Truces=w.Truces! with{Openings=[..w.Truces.Openings,new(p.Message,s.PlayerControl,w.ElapsedSeconds,w.CommitSequence)]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OldNullPolicyPreservesWorldBytesAndRejectsInjection(){var s=Start(false);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("Truce",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,Offer(s,10).Code);var w=s.DiagnosticSnapshot();w.Truces=new(1,TruceNegotiations.Policy,[],[],[],[]);Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void SaveDuringCounterReplyKeepsSameFutureFormationAndKnownConditions(){var s=Start();Send(s,90);var p=Last(s,TruceAction.Propose);Advance(s,Arrival(s,p)+1);var reply=Last(s,TruceAction.Counter);long at=Arrival(s,reply);Advance(s,at-1);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"truce-save-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"case",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));var b=host.Current;Export(s,b,"truce-counter-flight");Advance(s,at);Advance(b,at);Open(s,reply);Open(b,reply);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.TruceView()),ContractJson.Write(b.TruceView()));foreach(var session in new[]{s,b})Assert.Equal(ResultCode.Accepted,session.NegotiateTruce(new(new("request:restored-accept"),TruceAction.Accept,Own,Oda,reply.Input.Id),session.PlayerControl,session.Revision).Code);var accept=Last(s,TruceAction.Accept);Advance(s,Arrival(s,accept));Advance(b,Arrival(b,Last(b,TruceAction.Accept)));var confirm=Last(s,TruceAction.Confirm);Advance(s,Arrival(s,confirm));Advance(b,Arrival(b,Last(b,TruceAction.Confirm)));Open(s,confirm);Open(b,confirm);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.TruceView()),ContractJson.Write(b.TruceView()));s.SetPaused(true);Assert.True(store.Save(s,"formed",w.WorldId).Published);var again=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,again.CommitLoad(store.Prepare("formed"),again.Current,again.Current.Revision));Export(s,again.Current,"truce-formed");}

    [Fact]public void KnowledgeAndOwnWithdrawalAreNotASecretGlobalPeaceSwitch()
    {
        var s=Start();Assert.Equal(ResultCode.Accepted,s.DecideFactionStance(new(new("decision:own-war"),FactionStanceAction.DeclareHostile,Own,Oda,0,90*86400),s.PlayerControl,s.Revision).Code);ReceiveReply(s,10);var p=Last(s,TruceAction.Accept);Assert.Contains(FactionStances.Truth(s.DiagnosticSnapshot(),s.Seconds),h=>h.FromOwner==Own);Assert.False(TruceNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Own,Oda,s.Seconds,s.Revision));Open(s,p);var w=s.DiagnosticSnapshot();Assert.DoesNotContain(FactionStances.Truth(w,s.Seconds),h=>h.FromOwner==Own);Assert.True(TruceNegotiations.WillNotInitiate(w,Own,Oda,s.Seconds,s.Revision));Assert.False(TruceNegotiations.WillNotInitiate(w,Oda,Own,s.Seconds,s.Revision));var confirm=Last(s,TruceAction.Confirm);Advance(s,Arrival(s,confirm));w=s.DiagnosticSnapshot();Assert.True(TruceNegotiations.WillNotInitiate(w,Oda,Own,s.Seconds,s.Revision));Assert.Equal(2,w.Truces!.Fulfillments.Length);new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(w)));
        Assert.Equal(ResultCode.Accepted,s.DecideFactionStance(new(new("decision:late-hostility"),FactionStanceAction.DeclareHostile,Own,Oda,s.Seconds,s.Seconds+600),s.PlayerControl,s.Revision).Code);
        void Army(NewMilitaryAction action,long amount=0){var input=new NewMilitaryInput(new("request:truce-army/"+s.Revision),action,amount){AuthorityPolicy=action==NewMilitaryAction.Request?NewGameMilitary.AuthorityContract:null,LedgerPolicy=action==NewMilitaryAction.Request?NewGameMilitary.LedgerIdentityContract:null};var result=s.DecideNewMilitary(input,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
        void OpenMail(){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
        Army(NewMilitaryAction.Request);Advance(s,s.Seconds+2);OpenMail();Army(NewMilitaryAction.Accept);Advance(s,s.Seconds+2);OpenMail();Army(NewMilitaryAction.Pickup);Army(NewMilitaryAction.Load,100000);
        var permission=new NewMilitaryInput(new("request:truce-existing-engagement"),NewMilitaryAction.RequestEngagement){Engagement=new(NewGameMilitary.EngagementTaskContract,Oda,s.Seconds,s.Seconds+120)};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(permission,s.PlayerControl,s.Revision).Code);Advance(s,s.Seconds+2);OpenMail();Army(NewMilitaryAction.Deploy);w=s.DiagnosticSnapshot();Assert.Equal(100,w.Units.Where(u=>u.Organization==Own).Sum(u=>u.Soldiers));Assert.Contains(NewGameMilitary.EngagementMandates(w,s.Seconds),m=>m.TargetOwner==Oda&&m.ReceivedAt!=null);Assert.DoesNotContain(WorldEngagement.Snapshot(w).Mandates,m=>m.Owner==Own&&m.TargetOwner==Oda);Advance(s,s.Seconds+1);w=s.DiagnosticSnapshot();new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(w)));

    }
    [Fact]public void CounterCannotBeAcceptedAfterArrivalDeadline(){var s=Start();ReceiveReply(s,90);var p=Last(s,TruceAction.Counter);Open(s,p);Advance(s,p.Terms.ReplyBy+1);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.NegotiateTruce(new(new("request:too-late"),TruceAction.Accept,Own,Oda,p.Input.Id),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Empty(s.DiagnosticSnapshot().Truces!.Formations);}
    [Fact]public void DeclinedVersionCannotAlsoBeAcceptedByAnotherId(){var s=Start();ReceiveReply(s,90);var p=Last(s,TruceAction.Counter);Open(s,p);Assert.Equal(ResultCode.Accepted,s.NegotiateTruce(new(new("request:no"),TruceAction.Decline,Own,Oda,p.Input.Id),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.NegotiateTruce(new(new("request:yes"),TruceAction.Accept,Own,Oda,p.Input.Id),s.PlayerControl,s.Revision).Code);}
    [Fact]public void OwnOfferIsNotAnIncomingAcceptanceSource(){var s=Start();Send(s,10);var p=Last(s,TruceAction.Propose);Assert.Equal(ResultCode.NotAvailable,s.NegotiateTruce(new(new("request:self-accept"),TruceAction.Accept,Own,Oda,p.Input.Id),s.PlayerControl,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Truces!.Formations);}
    [Fact]public void SenderCanNotUseNpcResponseIdAsOwnIdempotentAction(){var s=Start();ReceiveReply(s,10);var p=Last(s,TruceAction.Accept);Assert.Equal(ResultCode.NotAvailable,s.NegotiateTruce(p.Input,s.PlayerControl,s.Revision).Code);}
    [Fact]public void ForgedFormationWithoutDeliveredAcceptanceIsRejected(){var s=Start();Send(s,10);var w=s.DiagnosticSnapshot();var p=w.Truces!.Papers[0];w.Truces=w.Truces with{Formations=[new(p.Input.Id,p.Terms,0,1)]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ExpiredAgreementDoesNotBlockFutureAttackIndefinitely(){var s=Start();ReceiveReply(s,1);var p=Last(s,TruceAction.Accept);Open(s,p);var until=p.Terms.Until;Assert.True(TruceNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Own,Oda,s.Seconds,s.Revision));Advance(s,until);Assert.False(TruceNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Own,Oda,s.Seconds,s.Revision));Assert.Contains(s.TruceView(),c=>c.Stage.Contains("期間終了"));}
    [Fact]public void ExistingCommonOrderIdCannotBeUsedAsProposalId(){var s=Start();var i=TravelWorld.Move(s.DiagnosticSnapshot(),"request:collision","castle");Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,Offer(s,10,"request:collision").Code);}

    static void Export(WorldSession a,WorldSession b,string name){var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(string.IsNullOrWhiteSpace(dir))return;Directory.CreateDirectory(dir);foreach(var item in new[]{(s:a,tag:"before"),(s:b,tag:"restored")})File.WriteAllBytes(Path.Combine(dir,name+"."+item.tag+".json"),ContractJson.Write(item.s.DiagnosticSnapshot()));}
    [Fact]public void UnopenedCounterDoesNotLeakNewVersionOrUntilIntoKnownCards(){var s=Start();ReceiveReply(s,90);var p=Last(s,TruceAction.Counter);Assert.Equal(2,p.Terms.Version);Assert.All(s.TruceView(),c=>Assert.Equal(1,c.Version));Open(s,p);Assert.Single(s.TruceView());Assert.Equal(2,s.TruceView()[0].Version);}
    [Fact]public void FormationRevisionMustFollowDispatchAndKnownFulfillmentCannotBeForged(){var s=Start();ReceiveReply(s,10);var w=s.DiagnosticSnapshot();var f=w.Truces!.Formations.Single();w.Truces=w.Truces with{Formations=[f with{Revision=1}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Truces=w.Truces! with{Fulfillments=[new(f.Acceptance,s.PlayerControl,w.ElapsedSeconds,w.CommitSequence,null)]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void PhysicallyLateLongDistancePaperCannotCreateDispatchBasedAgreement()
    {
        var scenario=NewGameWorld.Scenario();var site=scenario.Castles.Where(c=>c.Faction==null).OrderByDescending(c=>{var n=NationalRoutes.Nodes.Single(n=>RegionalCampaign.Site(n.Id).Value==c.Id);return (double)n.Position.NorthMm*n.Position.NorthMm;}).First();var p=NewGameWorldTests.Officer(role:StartTemplate.Daimyo,site:site.Id);var setup=NewGameWorldTests.Setup([p],[new(p.Id,Own.Value,[p.Site],false)]);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,p.Id,worldArmyPolicy:NpcArmies.CompactCombatPolicy,trucePolicy:TruceNegotiations.Policy));Send(s,1);var offer=Last(s,TruceAction.Propose);long arrival=Arrival(s,offer);Assert.True(arrival*2>86400,"selected long route must cross the receive deadline on at least one leg");Advance(s,arrival+1);var accept=s.DiagnosticSnapshot().Truces!.Papers.LastOrDefault(p=>p.Input.Action==TruceAction.Accept);if(accept!=null)Advance(s,Arrival(s,accept));Assert.Empty(s.DiagnosticSnapshot().Truces!.Formations);
    }
}
